1	//! Normalized conversation of an agent, persisted as a JSONL log of append/patch operations.
2	
3	use crate::model::ConvOp;
4	use crate::paths;
5	use serde_json::{json, Value};
6	use std::collections::HashMap;
7	use std::fs::{File, OpenOptions};
8	use std::io::{BufRead, BufReader, BufWriter, Write};
9	use std::path::{Path, PathBuf};
10	
11	pub struct Conv {
12	    dir: PathBuf,
13	    agent_id: String,
14	    loaded: bool,
15	    items: Vec<Value>,
16	    index: HashMap<String, usize>,
17	    writer: Option<BufWriter<File>>,
18	}
19	
20	impl Conv {
21	    pub fn new(dir: &Path, agent_id: &str) -> Self {
22	        Self {
23	            dir: dir.to_path_buf(),
24	            agent_id: agent_id.to_string(),
25	            loaded: false,
26	            items: Vec::new(),
27	            index: HashMap::new(),
28	            writer: None,
29	        }
30	    }
31	
32	    fn path(&self) -> PathBuf {
33	        log_path(&self.dir, &self.agent_id)
34	    }
35	
36	    pub fn ensure_loaded(&mut self) {
37	        if self.loaded {
38	            return;
39	        }
40	        self.loaded = true;
41	        if let Some(log) = replay(&self.path()) {
42	            self.take(log);
43	        }
44	    }
45	
46	    /// Takes the conversation as its log was read, and compacts the log when it holds many more
47	    /// operations than items. Not a log read in part only: rewritten from what was read, it would
48	    /// lose the rest for good. The operations to come are appended to it all the same.
49	    fn take(&mut self, log: Replayed) {
50	        self.loaded = true;
51	        self.items = log.items;
52	        self.index = log.index;
53	        if log.partial {
54	            log::warn!(
55	                "conversation of {} read in part only: its log is not compacted",
56	                self.agent_id
57	            );
58	        } else if log.ops > self.items.len() * 2 + 64 {
59	            self.compact();
60	        }
61	    }
62	
63	    /// Rewrites the log as one append per item.
64	    fn compact(&mut self) {
65	        self.writer = None;
66	        if let Err(e) = paths::write_atomic(&self.path(), appends(&self.items).as_bytes()) {
67	            log::warn!("conversation compaction failed: {e}");
68	        }
69	    }
70	
71	    fn apply_append(&mut self, item: Value) {
72	        append_item(&mut self.items, &mut self.index, item);
73	    }
74	
75	    fn apply_patch(&mut self, id: &str, patch: &Value) {
76	        patch_item(&mut self.items, &self.index, id, patch);
77	    }
78	
79	    /// Applies an operation in memory and persists it (streaming deltas are memory-only;
80	    /// the final text is persisted by a later patch).
81	    pub fn apply(&mut self, op: &ConvOp) {
82	        self.ensure_loaded();
83	        match op {
84	            ConvOp::Append { item } => self.apply_append(item.clone()),
85	            ConvOp::Patch { id, patch } => self.apply_patch(id, patch),
86	            ConvOp::Delta { id, text } => {
87	                if let Some(&i) = self.index.get(id) {
88	                    let cur = self.items[i]["text"].as_str().unwrap_or("").to_string();
89	                    self.items[i]["text"] = Value::String(cur + text);
90	                }
91	                return;
92	            }
93	        }
94	        self.persist(op);
95	    }
96	
97	    fn persist(&mut self, op: &ConvOp) {
98	        if self.writer.is_none() {
99	            let _ = std::fs::create_dir_all(&self.dir);
100	            match OpenOptions::new()
101	                .create(true)
102	                .append(true)
103	                .open(self.path())
104	            {
105	                Ok(f) => self.writer = Some(BufWriter::new(f)),
106	                Err(e) => {
107	                    log::warn!("cannot open conversation log: {e}");
108	                    return;
109	                }
110	            }
111	        }
112	        if let (Some(w), Ok(line)) = (self.writer.as_mut(), serde_json::to_string(op)) {
113	            let _ = w.write_all(line.as_bytes());
114	            let _ = w.write_all(b"\n");
115	            let _ = w.flush();
116	        }
117	    }
118	
119	    pub fn items(&mut self) -> Vec<Value> {
120	        self.ensure_loaded();
121	        self.items.clone()
122	    }
123	
124	    pub fn contains(&mut self, id: &str) -> bool {
125	        self.ensure_loaded();
126	        self.index.contains_key(id)
127	    }
128	
129	    pub fn get(&mut self, id: &str) -> Option<&Value> {
130	        self.ensure_loaded();
131	        self.index.get(id).map(|&i| &self.items[i])
132	    }
133	
134	    /// Items a turn left open: streaming text blocks (with their text so far, `Some`) and tools
135	    /// still running (`None`).
136	    pub fn open_items(&mut self) -> Vec<(String, Option<String>)> {
137	        self.ensure_loaded();
138	        self.items
139	            .iter()
140	            .filter_map(|v| {
141	                let id = v["id"].as_str()?.to_string();
142	                if v["streaming"] == true {
143	                    Some((id, Some(v["text"].as_str().unwrap_or("").to_string())))
144	                } else if v["kind"] == "tool" && v["status"] == "running" {
145	                    Some((id, None))
146	                } else {
147	                    None
148	                }
149	            })
150	            .collect()
151	    }
152	
153	    /// The latest item `pred` takes, without copying the others.
154	    pub fn last_where(&mut self, pred: impl Fn(&Value) -> bool) -> Option<&Value> {
155	        self.ensure_loaded();
156	        self.items.iter().rev().find(|v| pred(v))
157	    }
158	
159	    pub fn ids_where(&mut self, pred: impl Fn(&Value) -> bool) -> Vec<String> {
160	        self.ensure_loaded();
161	        self.items
162	            .iter()
163	            .filter(|v| pred(v))
164	            .filter_map(|v| v["id"].as_str().map(str::to_string))
165	            .collect()
166	    }
167	
168	    pub fn delete_file(&mut self) {
169	        self.writer = None;
170	        let _ = std::fs::remove_file(self.path());
171	    }
172	
173	    /// Lets go of the log's file, which stays: its agent leaves with its project's history.
174	    pub fn close_log(&mut self) {
175	        self.writer = None;
176	    }
177	
178	    /// Whether the log was read (tests only: reading it is what a closing must not do for
179	    /// nothing).
180	    #[cfg(test)]
181	    pub(crate) fn is_loaded(&self) -> bool {
182	        self.loaded
183	    }
184	}
185	
186	/// The log of an agent's conversation in the conversations' folder `dir`.
187	pub fn log_path(dir: &Path, agent_id: &str) -> PathBuf {
188	    dir.join(format!("{agent_id}.jsonl"))
189	}
190	
191	/// `items` as a log: one append each, in order.
192	fn appends(items: &[Value]) -> String {
193	    let mut out = String::new();
194	    for item in items {
195	        out.push_str(&json!({ "op": "append", "item": item }).to_string());
196	        out.push('\n');
197	    }
198	    out
199	}
200	
201	/// Writes the log of a new agent's conversation, which starts with `items` (a copy of another
202	/// agent's): one append each, the history of how they were written left out.
203	pub fn write_log(dir: &Path, agent_id: &str, items: &[Value]) -> std::io::Result<()> {
204	    std::fs::create_dir_all(dir)?;
205	    paths::write_atomic(&log_path(dir, agent_id), appends(items).as_bytes())
206	}
207	
208	/// What a conversation's log leaves once its operations are applied in order.
209	pub struct Replayed {
210	    pub items: Vec<Value>,
211	    /// Each item's place in `items`, by id.
212	    pub index: HashMap<String, usize>,
213	    /// The operations read.
214	    pub ops: usize,
215	    /// The reading failed before the end of the log (a disk error, not a damaged line): what
216	    /// follows is not in `items`.
217	    pub partial: bool,
218	}
219	
220	/// Reads a log back, without writing anything: the search reads the logs of agents that are
221	/// writing theirs. A line that is no operation (cut short as the app stopped while writing it,
222	/// damaged, not even UTF-8) is skipped and the reading goes on: the log is compacted from what is
223	/// read. None when there is no log.
224	pub fn replay(path: &Path) -> Option<Replayed> {
225	    let file = File::open(path).ok()?;
226	    Some(replay_from(BufReader::new(file)))
227	}
228	
229	/// `replay` of the log `reader` gives.
230	fn replay_from(reader: impl BufRead) -> Replayed {
231	    let mut log = Replayed {
232	        items: Vec::new(),
233	        index: HashMap::new(),
234	        ops: 0,
235	        partial: false,
236	    };
237	    // Lines as bytes: reading them as text would stop at the first one that is not UTF-8.
238	    for line in reader.split(b'\n') {
239	        let line = match line {
240	            Ok(line) => line,
241	            Err(e) => {
242	                log::warn!("conversation log read in part only: {e}");
243	                log.partial = true;
244	                break;
245	            }
246	        };
247	        let Ok(v) = serde_json::from_slice::<Value>(&line) else {
248	            continue;
249	        };
250	        log.ops += 1;
251	        match v["op"].as_str() {
252	            Some("append") => append_item(&mut log.items, &mut log.index, v["item"].clone()),
253	            Some("patch") => {
254	                if let Some(id) = v["id"].as_str() {
255	                    patch_item(&mut log.items, &log.index, id, &v["patch"]);
256	                }
257	            }
258	            _ => {}
259	        }
260	    }
261	    log
262	}
263	
264	/// An item appended again (same id) replaces the one in place.
265	fn append_item(items: &mut Vec<Value>, index: &mut HashMap<String, usize>, item: Value) {
266	    let Some(id) = item["id"].as_str().map(str::to_string) else {
267	        return;
268	    };
269	    if let Some(&i) = index.get(&id) {
270	        items[i] = item;
271	    } else {
272	        index.insert(id, items.len());
273	        items.push(item);
274	    }
275	}
276	
277	fn patch_item(items: &mut [Value], index: &HashMap<String, usize>, id: &str, patch: &Value) {
278	    let Some(&i) = index.get(id) else { return };
279	    if let (Some(target), Some(fields)) = (items[i].as_object_mut(), patch.as_object()) {
280	        for (k, v) in fields {
281	            target.insert(k.clone(), v.clone());
282	        }
283	    }
284	}
285	
286	#[cfg(test)]
287	mod tests {
288	    use super::*;
289	    use crate::paths::test_dir;
290	
291	    #[test]
292	    fn a_new_log_holds_the_items_given_one_append_each() {
293	        let dir = test_dir("conv-write-log");
294	        let items: Vec<Value> = (0..3)
295	            .map(|i| json!({ "kind": "user", "id": format!("u{i}"), "text": format!("m{i}") }))
296	            .collect();
297	        // Its folder is made when there is none yet.
298	        let conversations = dir.join("conversations");
299	        write_log(&conversations, "copy", &items).unwrap();
300	        let log = replay(&log_path(&conversations, "copy")).unwrap();
301	        assert_eq!(log.items, items);
302	        assert_eq!(log.ops, 3);
303	        assert_eq!(Conv::new(&conversations, "copy").items(), items);
304	    }
305	
306	    #[test]
307	    fn reads_on_past_a_line_that_is_not_utf8_and_compacts_without_losing_what_follows() {
308	        let dir = test_dir("conv-utf8");
309	        let op = |v: Value| format!("{v}\n").into_bytes();
310	        let mut bytes = op(
311	            json!({ "op": "append", "item": { "kind": "text", "id": "m1", "text": "", "streaming": true } }),
312	        );
313	        // Enough operations for the log to be compacted once read.
314	        for i in 0..70 {
315	            bytes.extend(op(
316	                json!({ "op": "patch", "id": "m1", "patch": { "text": format!("v{i}") } }),
317	            ));
318	        }
319	        bytes
320	            .extend_from_slice(b"{\"op\":\"patch\",\"id\":\"m1\",\"patch\":{\"text\":\"\xff\"}}\n");
321	        bytes.extend(op(
322	            json!({ "op": "append", "item": { "kind": "user", "id": "u2", "text": "après" } }),
323	        ));
324	        std::fs::write(log_path(&dir, "a1"), bytes).unwrap();
325	        let ids = |items: &[Value]| -> Vec<String> {
326	            items
327	                .iter()
328	                .map(|i| i["id"].as_str().unwrap().to_string())
329	                .collect()
330	        };
331	        let mut conv = Conv::new(&dir, "a1");
332	        assert_eq!(ids(&conv.items()), ["m1", "u2"]);
333	        assert_eq!(conv.get("m1").unwrap()["text"], "v69");
334	        // Compacted: one append per item, the one after the bad line included.
335	        let log = replay(&log_path(&dir, "a1")).unwrap();
336	        assert_eq!(log.ops, 2);
