1	//! Recorded real streams of a harness, replayed through its translation and compared with the
2	//! items expected (docs/ENGINES.md, « Les flux enregistrés »).
3	//!
4	//! A case is a JSON file of `tests/fixtures/replays/<engine>/`:
5	//!
6	//! ```json
7	//! {
8	//!   "about": "What was recorded, with which version, and what it shows.",
9	//!   "flux": "../../real-run-send-message.jsonl",
10	//!   "agent": { "cwd": "C:\\Users\\dev\\repo" },
11	//!   "items": [ { "kind": "text", "text": "Bonjour", "parent": null } ],
12	//!   "agentAfter": { "sessionId": "…", "status": "done" }
13	//! }
14	//! ```
15	//!
16	//! - `flux`: the stream as it was recorded, one frame (a JSON value) a line, left as it came;
17	//!   relative to the case.
18	//! - `agent` (optional): what the agent is before the first frame, over a new agent's defaults,
19	//!   as its state is saved (`AgentMeta`, camelCase).
20	//! - `items`: the conversation the frames make, in order, without its `id` nor its times (`ts`,
21	//!   `startedAt`, `endedAt`), made up at each replay. Each expected item is compared with the one
22	//!   made by what it says only: a key it leaves out is not compared (an object's keys within it
23	//!   neither; a list has its length). Numbers are compared to their last bit.
24	//! - `agentAfter` (optional): what the agent is after the last frame, compared the same way
25	//!   (without its times either).
26	//!
27	//! With `ESCOUADE_BLESS=1`, a case is written again from what its frames make (its `items` and the
28	//! keys of its `agentAfter`, or a few of them when it has none) instead of compared: the diff is
29	//! then read before it is committed.
30	
31	use crate::agent::{AgentRt, Effects};
32	use crate::engine::Engine;
33	use crate::model::AgentMeta;
34	use serde_json::{json, Map, Value};
35	use std::path::{Path, PathBuf};
36	
37	/// The times of an item, made up at each replay (its `id` too, at its top).
38	const TIMES: [&str; 3] = ["ts", "startedAt", "endedAt"];
39	
40	/// `v` without the times of the replay (`TIMES`), at any depth.
41	fn strip_times(v: &mut Value) {
42	    match v {
43	        Value::Object(o) => {
44	            for k in TIMES {
45	                o.remove(k);
46	            }
47	            o.values_mut().for_each(strip_times);
48	        }
49	        Value::Array(a) => a.iter_mut().for_each(strip_times),
50	        _ => {}
51	    }
52	}
53	
54	/// The keys of the agent a blessed case keeps when it says none.
55	const AFTER: [&str; 6] = [
56	    "sessionId",
57	    "lastEntry",
58	    "status",
59	    "touchedFiles",
60	    "tokens",
61	    "cost",
62	];
63	
64	/// The folder of the cases of `engine` (`claude`).
65	pub(crate) fn cases_of(engine: &str) -> PathBuf {
66	    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
67	        .join("..")
68	        .join("tests")
69	        .join("fixtures")
70	        .join("replays")
71	        .join(engine)
72	}
73	
74	/// What the frames of a case made: the conversation without its volatile keys, and the agent.
75	pub(crate) struct Replayed {
76	    pub items: Vec<Value>,
77	    pub agent: Value,
78	}
79	
80	/// The frames of `flux`, one a line, through the translation of `engine`, for an agent that is
81	/// `agent` (over a new agent's defaults) before the first.
82	pub(crate) fn replay(engine: &dyn Engine, flux: &str, agent: &Value, conv: &Path) -> Replayed {
83	    let mut meta = serde_json::to_value(AgentMeta {
84	        id: crate::model::new_id(),
85	        ..Default::default()
86	    })
87	    .unwrap();
88	    if let Some(over) = agent.as_object() {
89	        for (k, v) in over {
90	            meta[k] = v.clone();
91	        }
92	    }
93	    let meta: AgentMeta = serde_json::from_value(meta).expect("the case's agent");
94	    let mut rt = AgentRt::new(meta, conv);
95	    for (n, line) in flux
96	        .lines()
97	        .enumerate()
98	        .filter(|(_, l)| !l.trim().is_empty())
99	    {
100	        let frame: Value = serde_json::from_str(line)
101	            .unwrap_or_else(|e| panic!("line {} of the flux is no JSON: {e}", n + 1));
102	        engine.translate(&mut rt, &frame, &mut Effects::default());
103	    }
104	    // A harness that tells no duration of its turns has them timed by Escouade, from the start of
105	    // the turn (made up at each replay as the times are): there must be one, and it is not kept.
106	    let timed = matches!(
107	        engine.id(),
108	        crate::model::EngineId::Copilot
109	            | crate::model::EngineId::Opencode
110	            | crate::model::EngineId::Cursor
111	            | crate::model::EngineId::Vibe
112	            | crate::model::EngineId::Agy
113	            | crate::model::EngineId::Gemini
114	    );
115	    let items = rt
116	        .conv
117	        .items()
118	        .into_iter()
119	        .map(|mut item| {
120	            if let Some(o) = item.as_object_mut() {
121	                o.remove("id");
122	                if timed && o.get("kind").and_then(Value::as_str) == Some("turn") {
123	                    assert!(
124	                        o.get("durationMs").is_some_and(Value::is_u64),
125	                        "a turn of {} with no duration: {o:?}",
126	                        engine.id().as_str()
127	                    );
128	                    o.insert("durationMs".into(), Value::Null);
129	                }
130	            }
131	            strip_times(&mut item);
132	            item
133	        })
134	        .collect();
135	    // The times of its plan too (its subagents' `startedAt`, `endedAt`).
136	    let mut agent = serde_json::to_value(&rt.meta).unwrap();
137	    strip_times(&mut agent);
138	    Replayed { items, agent }
139	}
140	
141	/// Replays the case `case` through `engine` and compares what it made with what it expects (or
142	/// writes it again, `ESCOUADE_BLESS`). Panics on the first difference, saying where.
143	pub(crate) fn check(engine: &dyn Engine, case: &Path) {
144	    let name = case.display();
145	    let mut c: Value =
146	        serde_json::from_slice(&std::fs::read(case).unwrap_or_else(|e| panic!("{name}: {e}")))
147	            .unwrap_or_else(|e| panic!("{name}: {e}"));
148	    let flux_path = case.parent().unwrap().join(
149	        c["flux"]
150	            .as_str()
151	            .unwrap_or_else(|| panic!("{name}: no flux")),
152	    );
153	    let flux = std::fs::read_to_string(&flux_path)
154	        .unwrap_or_else(|e| panic!("{name}: {}: {e}", flux_path.display()));
155	    let conv = crate::paths::test_dir(&format!(
156	        "replay-{}-{}",
157	        engine.id().as_str(),
158	        case.file_stem().unwrap().to_string_lossy()
159	    ));
